function head(string $title,string $description,string $path,bool $noindex=false):void{\BSPResearch\security();if($noindex){header('X-Robots-Tag: noindex');header('Cache-Control: no-store');}$url=\BSPResearch\ORIGIN.$path;?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?> | Beyond Spacetime</title><meta name="description" content="<?=h($description)?>"><meta name="robots" content="<?=$noindex?'noindex, follow':'index, follow'?>"><link rel="canonical" href="<?=h($url)?>"><meta property="og:title" content="<?=h($title)?>"><meta property="og:description" content="<?=h($description)?>"><meta property="og:url" content="<?=h($url)?>"><meta property="og:image" content="https://beyondspacetime.org/evidence/assets/banner.webp"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/research/assets/research.css?v=1.5.0"><link rel="stylesheet" href="/model-comparison/assets/comparison.css?v=1.6.0"><script src="/model-comparison/assets/comparison.js?v=1.6.0" defer></script><script type="application/ld+json"><?=j(['@context'=>'https://schema.org','@graph'=>[['@type'=>'WebPage','name'=>$title,'url'=>$url,'description'=>$description,'isPartOf'=>['@type'=>'WebSite','name'=>'Beyond Spacetime','url'=>\BSPResearch\ORIGIN.'/']],['@type'=>'BreadcrumbList','itemListElement'=>[['@type'=>'ListItem','position'=>1,'name'=>'Home','item'=>\BSPResearch\ORIGIN.'/'],['@type'=>'ListItem','position'=>2,'name'=>'Model comparison','item'=>\BSPResearch\ORIGIN.ROOT]]]]])?></script><link rel="stylesheet" href="/museum/assets/crossnav.css?v=2.2.1"></head><body><a class="skip" href="#main">Skip to content</a><header><div class="nav"><a class="brand" href="/"><img src="/evidence/assets/compass.png" width="46" height="46" alt=""><span>BEYOND<span class="gold">SPACETIME</span><small>THE EXPLAINER PROJECT</small></span></a><nav aria-label="Main navigation"><?php if(\bsp_legacy_available()):?><a href="/explore/">Explore 3D</a><?php endif;?><a href="/foundations/">Foundations</a><a href="/evidence/">Evidence</a><a href="/research/">Research</a><a href="/model-comparison/" <?=$path===ROOT?'aria-current="page"':''?>>Model comparison</a><a href="/model-comparison/protocol/" <?=$path!==ROOT?'aria-current="page"':''?>>API guide</a></nav><a class="arc" href="https://arcsecs.com/read-scientific-paper/">Original research ↗</a></div></header><nav class="museum-crossnav" aria-label="Museum exhibits"><a href="/museum/">Museum</a><a href="/museum/search/">Search</a><a href="/foundations/">Foundations</a><a href="/evidence/">Evidence</a><a href="/research/">Workspace</a><a href="/model-comparison/" aria-current="true">Compare</a><a href="/timeline/">Timeline</a><a href="/global/">Languages</a><a href="/offline/">Offline</a><a href="/visualizations/">Visualize</a><a href="/knowledge-graph/">Graph</a><a href="/experiment-design/">Design</a><a href="/universal-time/">Time</a></nav><main class="wrap" id="main"><div class="crumb"><a href="/">Home</a> / <a href="/model-comparison/">Model comparison</a></div><?php }
function foot():void{?><footer><div><strong>Beyond Spacetime · Model comparison</strong><p>Conditional educational calculations, not observational fits. Original publications remain on ArcSecs.</p></div><div><a href="/model-comparison/catalog.json">Machine catalog</a><a href="/model-comparison/protocol/">API guide</a><a href="/model-comparison/sitemap.xml">Sitemap</a></div><div><a href="/research/">Research workspace</a><a href="/evidence/">Evidence ledger</a><a href="https://arcsecs.com/">ArcSecs ↗</a></div></footer></main></body></html><?php }
function plot(array $r,bool $delta):void{$rows=$r['rows'];$keys=$delta?['delta']:['candidate','reference'];$lo=0.;$hi=0.;foreach(array_merge($rows,[$r['probe']['lower'],$r['probe']['center'],$r['probe']['upper']]) as $row)foreach($keys as $k){$lo=min($lo,$row[$k]);$hi=max($hi,$row[$k]);}if($hi==$lo)$hi=$lo+1;$a=$r['plan']['start'];$b=$r['plan']['end'];$x=fn($v)=>85+($v-$a)/($b-$a)*590;$y=fn($v)=>220-($v-$lo)/($hi-$lo)*190;?><figure class="cmp-plot"><h3><?=$delta?'Difference · candidate minus reference':'Shared observable scale'?></h3><svg viewBox="0 0 700 270" role="img" aria-label="<?=h(($delta?'Difference':'Candidate and reference').' by '.$r['parameter_label'])?>"><?php for($i=0;$i<=4;$i++):$v=$lo+($hi-$lo)*$i/4;$z=$a+($b-$a)*$i/4;?><line x1="85" x2="675" y1="<?=$y($v)?>" y2="<?=$y($v)?>" class="gridline"/><text x="79" y="<?=$y($v)+4?>" text-anchor="end"><?=h(fmt($v))?></text><text x="<?=$x($z)?>" y="238" text-anchor="middle"><?=h(fmt($z))?></text><?php endfor;?><rect x="<?=$x($r['probe']['lower']['x'])?>" y="30" width="<?=max(0,$x($r['probe']['upper']['x'])-$x($r['probe']['lower']['x']))?>" height="190" class="probe-band"/><?php foreach($keys as $k):?><polyline class="cmp-series cmp-<?=$k?>" points="<?=h(implode(' ',array_map(fn($z)=>sprintf('%.2f,%.2f',$x($z['x']),$y($z[$k])),$rows)))?>"/><circle cx="<?=$x($r['probe']['center']['x'])?>" cy="<?=$y($r['probe']['center'][$k])?>" r="4" class="cmp-dot cmp-<?=$k?>"/><?php endforeach;?><text x="380" y="263" text-anchor="middle"><?=h($r['parameter_label'])?></text></svg><figcaption><?=$delta?'Mint: candidate − reference.':'Gold: candidate. Blue dashed: reference.'?> Shaded band: sensitivity interval; dot: exact probe value. <?=h($r['unit'])?></figcaption></figure><?php }
function result(array $r):void{$p=$r['plan'];$probe=$r['probe'];?><section class="section" id="results"><div class="section-heading"><div><span class="eyebrow">COMPUTED EVIDENCE</span><h2><?=h($p['title'])?></h2></div><span class="pill"><?=count($r['rows'])?> samples</span></div><p><?=h($p['description'])?></p><p class="notice"><?=h($r['interpretation'])?></p><p><strong>Model limitation:</strong> <?=h($r['model_limitation'])?></p><?php if($r['equation']):?><p class="notice"><?=h($r['equation'])?></p><?php endif;?><div class="cmp-metrics"><div><small>Candidate at probe · <?=h($p['metric'])?></small><strong><?=h(fmt($probe['center']['candidate']))?> <?=h($r['unit'])?></strong></div><div><small>Reference at probe · <?=h($p['reference_metric'])?></small><strong><?=h(fmt($probe['center']['reference']))?> <?=h($r['unit'])?></strong></div><div><small>Difference at probe</small><strong><?=h(fmt($probe['center']['delta']))?></strong></div><div><small>Difference secant slope</small><strong><?=h($probe['secant_slopes']['delta']===null?'Undefined':fmt($probe['secant_slopes']['delta']))?></strong></div></div><div class="cmp-charts"><?php plot($r,false);plot($r,true);?></div><section class="panel"><h3>Local parameter sensitivity</h3><p>Evaluate exact model outputs at the center and the interval endpoints. This is a deterministic variation of one input, not a statistical error estimate. <?=$probe['clipped']?'The interval is clipped to the selected sweep range.':''?></p><div class="table-scroll"><table><thead><tr><th scope="col">Probe</th><th scope="col">Parameter</th><th scope="col">Candidate</th><th scope="col">Reference</th><th scope="col">Difference</th></tr></thead><tbody><?php foreach(['lower','center','upper'] as $k):?><tr><th scope="row"><?=h(ucfirst($k))?></th><?php foreach(['x','candidate','reference','delta'] as $f):?><td><?=h(fmt($probe[$k][$f]))?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section><div class="actions"><button type="button" id="cmp-json" hidden>Export full JSON</button><button type="button" id="cmp-csv" class="secondary" hidden>Export sweep CSV</button><button type="button" id="cmp-recipe" class="secondary" hidden>Save recipe</button></div><details class="panel"><summary>All numerical samples</summary><div class="table-scroll"><table><thead><tr><?php foreach([$r['parameter_label'],'Candidate','Reference','Difference'] as $s):?><th scope="col"><?=h($s)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($r['rows'] as $row):?><tr><?php foreach(['x','candidate','reference','delta'] as $k):?><td><?=h(fmt($row[$k]))?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></details><section class="section"><h3>Trace the evidence</h3><p><a href="<?=h($r['source']['url'])?>">Original scientific review ↗</a> · <a href="<?=h($r['model_url'])?>">Original learning model →</a> · <a href="/research/">Multi-case research workspace →</a></p><div class="cmp-evidence"><?php foreach($r['evidence'] as $e):?><article class="panel"><h3><a href="<?=h($e['url'])?>"><?=h($e['title'])?></a></h3><p><?=h($e['classification']??$e['status']??'Research record')?></p></article><?php endforeach;?></div><details class="panel"><summary>Reproducibility and source hashes</summary><p>Recipe SHA-256: <code><?=h($r['plan_sha256'])?></code></p><p>Result SHA-256: <code><?=h($r['result_sha256'])?></code></p><p>PHP <?=h($r['provenance']['php_version'])?>. The export contains source hashes and the complete normalized plan. A digest identifies this calculation, not scientific authenticity.</p></details></section><script type="application/json" id="cmp-result"><?=j($r)?></script></section><?php }
